// Lógica simples de resposta do bot
const userMessage = $input.item.json.content.toLowerCase();
let botResponse = "";

// Saudações
if (userMessage.includes('olá') || userMessage.includes('oi') || userMessage.includes('hey')) {
  botResponse = "Olá! 👋 Como posso ajudar você hoje?";
}
// Ajuda
else if (userMessage.includes('ajuda') || userMessage.includes('help')) {
  botResponse = "Estou aqui para ajudar! Você pode me perguntar sobre:\n\n• Informações gerais\n• Enviar imagens\n• Gravar áudios\n• E muito mais!\n\nO que você gostaria de saber?";
}
// Piadas
else if (userMessage.includes('piada') || userMessage.includes('joke')) {
  const piadas = [
    "Por que o livro de matemática se suicidou? Porque tinha muitos problemas! 😄",
    "O que o pato disse para a pata? Vem Quá! 🦆",
    "Por que a galinha atravessou a rua? Para provar que não era frango! 🐔"
  ];
  botResponse = piadas[Math.floor(Math.random() * piadas.length)];
}
// Horário
else if (userMessage.includes('horas') || userMessage.includes('hora')) {
  const now = new Date();
  botResponse = `Agora são ${now.toLocaleTimeString('pt-BR')} ⏰`;
}
// Data
else if (userMessage.includes('data') || userMessage.includes('dia')) {
  const now = new Date();
  botResponse = `Hoje é ${now.toLocaleDateString('pt-BR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })} 📅`;
}
// Resposta padrão
else {
  botResponse = `Você disse: "${$input.item.json.content}"\n\nSou um bot simples, mas estou aqui para ajudar! Digite "ajuda" para ver o que posso fazer. 🤖`;
}

// Retornar resposta no formato esperado pelo app
return {
  success: true,
  response: {
    type: "text",
    text: botResponse,
    data: null
  },
  metadata: {
    processedAt: new Date().toISOString(),
    userId: $input.item.json.userId
  }
};

// Processar imagem recebida
const imageData = $input.item.json.content; // base64 ou URL
const userId = $input.item.json.userId;

// Aqui você pode:
// 1. Salvar a imagem em storage (S3, Cloudinary, etc)
// 2. Analisar a imagem com IA (Google Vision, AWS Rekognition)
// 3. Processar OCR para extrair texto
// 4. Fazer reconhecimento facial
// etc.

// Por enquanto, apenas confirma recebimento
return {
  success: true,
  response: {
    type: "text",
    text: "📸 Imagem recebida com sucesso! Obrigado por compartilhar.\n\nEm uma versão avançada, eu poderia analisar sua imagem e descrever o que vejo.",
    data: null
  },
  metadata: {
    processedAt: new Date().toISOString(),
    userId: userId,
    imageSize: imageData ? imageData.length : 0
  }
};

// Processar áudio recebido
const audioData = $input.item.json.content; // base64
const userId = $input.item.json.userId;

// Aqui você pode:
// 1. Salvar o áudio
// 2. Converter para texto (Speech-to-Text)
// 3. Analisar sentimentos na voz
// 4. Responder com áudio (Text-to-Speech)
// etc.

return {
  success: true,
  response: {
    type: "text",
    text: "🎤 Áudio recebido!\n\nEm uma versão avançada, eu poderia transcrever seu áudio e responder com voz.",
    data: null
  },
  metadata: {
    processedAt: new Date().toISOString(),
    userId: userId,
    audioSize: audioData ? audioData.length : 0
  }
};
